namespace UnityTcp.ShaderTools
{
    /// <summary>
    /// ShaderGraph MCP 工具集（反射版）—— 从 Assembly-CSharp-Editor 通过反射访问 internal API。
    /// 所有 ShaderGraph 内部类型通过 SGReflection 访问，与 Packages 原版零耦合。
